import { finite, sum, normalizeWeights, metrics, valuation, scenarios, portfolioAnalysis, alignReturns, returnStats, validateSnapshot } from './analytics.mjs';
import { sparkline, portfolioChart, lineChart, heatmap, scatter, forecastCone, histogram } from './charts.mjs';
import { registerPortfolio, reviewPortfolio, DEFAULT_RULES } from './monitor.mjs';

const $ = (s, root = document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url = s => /^https:\/\//.test(s || '') ? esc(s) : '#';
const fmt = (v, n = 2) => finite(v) ? v.toLocaleString('en-US', {minimumFractionDigits:n,maximumFractionDigits:n}) : '—';
const pct = (v, n = 1, signed = false) => finite(v) ? `${signed && v > 0 ? '+' : ''}${fmt(v*100,n)}%` : '—';
const money = (v, n = 2) => finite(v) ? '$'+fmt(v,n) : '—';
const compact = v => !finite(v) ? '—' : Math.abs(v)>=1e12 ? '$'+fmt(v/1e12,2)+' T' : Math.abs(v)>=1e9 ? '$'+fmt(v/1e9,2)+' B' : '$'+fmt(v/1e6,1)+' M';
const color = x => finite(x) ? x >= 0 ? 'positive' : 'negative' : 'muted';
const dateLabel = d => d && /^\d{4}-\d{2}-\d{2}/.test(d) ? new Date(d.slice(0,10)+'T12:00:00Z').toLocaleDateString('es-PE',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).replaceAll('.','').toUpperCase() : '—';
const icon = key => ({arrow:'<span aria-hidden="true">»</span>',download:'<span aria-hidden="true">↓</span>',upload:'<span aria-hidden="true">↑</span>',close:'<span aria-hidden="true">×</span>',refresh:'<span aria-hidden="true">↻</span>',data:'<span aria-hidden="true">DATOS</span>',help:'<span aria-hidden="true">AYUDA</span>',search:'<span aria-hidden="true">/</span>'}[key]||'');
const NAV = [['portfolio','Componer cartera','F1'],['overview','Seguimiento','F2'],['forecasts','Proyecciones','F3'],['research','Research','F4'],['valuation','Valoración','F5'],['risk','Riesgo','F6'],['macro','Macro monitor','F7']];
let saved = {};
try { saved = JSON.parse(localStorage.getItem('trading-workspace-v1') || '{}'); } catch {}
const state = { view:'portfolio', positions:[], capital:100000, lookback:252, chartMode:'forecast', selected:'MSFT', method:'pe', overrides:{},baseline:null,acknowledged:[],rules:{...DEFAULT_RULES},
  filters:{text:'',sector:'all',discount:false,type:'all'}, sort:{key:'symbol',ascending:true}, forecast:null, validation:null, busy:false, forecastError:null,
  settings:{model:'merton',horizon:1,paths:3000,seed:20261024,driftMode:'fundamental',manualReturn:.06,lambda:.94,jumpIntensity:.35,jumpMean:-.12,jumpVol:.08}, ...saved };
state.view = NAV.some(n=>n[0]===state.view) ? state.view : 'portfolio';
state.forecast = null; state.validation = null; state.busy = false; state.forecastError = null; state.rules={...DEFAULT_RULES,...state.rules}; state.acknowledged=Array.isArray(state.acknowledged)?state.acknowledged:[];
state.filters={text:'',sector:'all',discount:false,type:'all'}; state.sort={key:'symbol',ascending:true};
let data, worker, job = 0, toastTimer, weightTimer, lastFocus, statsCache = new Map();

function persist() {
  try { localStorage.setItem('trading-workspace-v1',JSON.stringify({positions:state.positions,capital:state.capital,lookback:state.lookback,selected:state.selected,overrides:state.overrides,settings:state.settings,view:state.view,baseline:state.baseline,acknowledged:state.acknowledged,rules:state.rules})); } catch {}
}
function toast(message) { const t=$('#toast'); t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500); }
function asset(symbol) { return data.assets.find(a=>a.symbol===symbol); }
function override(symbol) { return state.overrides?.[symbol] || {}; }
function model(a, method='pe') { return valuation(a,override(a.symbol),method); }
function riskFree() { return (data.macro.find(s=>s.id==='DGS3MO')?.value ?? 4)/100; }
function analyze(positions=state.positions,lookback=state.lookback) { return portfolioAnalysis(data.assets,positions,lookback,riskFree()); }
function assetStats(a) { const key=a.symbol+':'+state.lookback;if(!statsCache.has(key)){const alignment=alignReturns([a,asset('SPY')||a],state.lookback);statsCache.set(key,returnStats(alignment.columns[0],riskFree(),alignment.columns[1]));}return statsCache.get(key); }
function panel(title,index,body,controls='',foot='') { return `<section class="panel"><div class="panel-header"><h2 class="panel-title"><span class="panel-index">${index}</span>${title}</h2>${controls}</div>${body}${foot?`<div class="chart-footnote">${foot}</div>`:''}</section>`; }
function metric(label,value,sub='',className='',unit='') { return `<div class="metric-card"><div class="metric-label">${label}${icon('forecasts')}</div><div class="metric-value ${className}">${value}${unit?`<span class="unit">${unit}</span>`:''}</div><div class="metric-bottom"><span class="mini-square"></span>${sub}</div></div>`; }
function title(eyebrow,heading,subtitle,actions='') { return `<div class="page-title"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="subtitle">${subtitle}</p></div><div class="page-actions">${actions}</div></div>`; }
function simulationMetrics() {
  const f=state.forecast;
  return `<div class="metric-grid">${metric('RETORNO MEDIANO · MODELO',f?pct(f.medianReturn):'—',`Horizonte ${state.settings.horizon*12} meses · percentil 50`,f?color(f.medianReturn):'')}${metric('PROBABILIDAD DE PÉRDIDA',f?pct(f.lossProbability):'—','Condicional a los supuestos del modelo',f&&f.lossProbability>.5?'negative':'')}${metric('VAR 95% · HORIZONTE',f?pct(f.var95):'—',f?`${money(f.var95*state.capital,0)} sobre capital simulado`:'Monte Carlo correlacionado','negative')}${metric('CVAR 95% · HORIZONTE',f?pct(f.cvar95):'—','Pérdida media en el peor 5%','negative')}</div>`;
}
function allocation(a) {
  const w=a?.weights||[];
  return `<div class="table-wrap"><table class="allocation-table"><thead><tr><th>ACTIVO</th><th>PESO</th><th>EXPOSICIÓN</th></tr></thead><tbody>${w.map(p=>`<tr><td><button class="text-button" data-detail="${p.symbol}">${esc(p.symbol)}</button></td><td>${pct(p.weight,1)}</td><td><div class="allocation-track"><span style="width:${p.weight*100}%"></span></div></td></tr>`).join('')}</tbody></table></div><div class="allocation-summary"><div><label>CAPITAL SIMULADO</label><strong>${money(state.capital,0)}</strong></div><div><label>POSICIONES EFECTIVAS</label><strong>${fmt(a?.effectivePositions,1)}</strong></div></div>`;
}

function forecastPanel(full=false) {
  const f=state.forecast, historical=state.chartMode==='history'&&!full, analysis=historical?analyze():null;
  const legend=historical?'<span><i class="legend-line"></i>Cartera</span><span><i class="legend-line benchmark"></i>SPY</span>':'<span><i class="legend-line"></i>Mediana</span><span class="muted">Bandas 50% / 90%</span>';
  const resultCards=historical?`<div class="forecast-bands">${[['VOLATILIDAD ANUAL',analysis?.stats.volatility,''],['DRAWDOWN MÁXIMO',analysis?.stats.maxDrawdown,'negative'],['RETORNO SPY',analysis?.benchmarkStats.total,'']].map(([l,v,c])=>`<div class="forecast-band"><label>${l}</label><strong class="${c}">${pct(v)}</strong><small>${analysis?.stats.n||0} sesiones comunes</small></div>`).join('')}</div>`:f?`<div class="forecast-bands">${[['P05 · ADVERSO',f.p05,'negative'],['P50 · MEDIANA',f.medianReturn,'orange'],['P95 · FAVORABLE',f.p95,'positive']].map(([label,r,c])=>`<div class="forecast-band"><label>${label}</label><strong class="${c}">${money(state.capital*(1+r),0)}</strong><small>${pct(r,1,true)} en ${state.settings.horizon*12} meses</small></div>`).join('')}</div>`:'';
  return panel(historical?'EVOLUCIÓN HISTÓRICA':'DISTRIBUCIÓN DE RESULTADOS','01',`${state.busy?'<div class="prediction-progress"></div>':''}<div class="chart-body"><div class="chart-summary"><div><span class="summary-label">${historical?'RETORNO ACUMULADO · CARTERA':'CAPITAL PROYECTADO · P50'}</span><strong>${historical?pct(analysis?.stats.total,1,true):f?money(state.capital*(1+f.medianReturn),0):'—'}</strong></div><div class="chart-legend">${legend}</div></div>${historical?portfolioChart(analysis):forecastCone(f,full?310:265)}</div>${resultCards}`,
    full?`<span class="panel-meta">${state.settings.paths.toLocaleString('en-US')} TRAYECTORIAS</span>`:`<div class="panel-controls"><button class="range-button ${state.chartMode==='forecast'?'active':''}" data-chart="forecast">PROYECCIÓN</button><button class="range-button ${state.chartMode==='history'?'active':''}" data-chart="history">HISTÓRICO</button></div>`,
    `<span>${historical?'Pesos constantes · base 100 · sin costos':`${state.settings.model==='merton'?'Difusión con saltos':'Movimiento browniano geométrico'} · buy & hold · base 100`}</span><span>${historical?'VENTANA '+state.lookback+'D':'SUPUESTOS EDITABLES'}</span>`);
}

function riskMonitor(a) { const s=a?.stats;return panel('RIESGO HISTÓRICO','05',`<div class="risk-strip">${[['Volatilidad anual',pct(s?.volatility)],['Caída máxima histórica',pct(s?.maxDrawdown)],['Beta vs SPY',fmt(s?.beta)],['VaR histórico · 1 día',pct(s?.var95)],['Sharpe histórico',fmt(s?.sharpe)]].map(([l,v])=>`<div class="risk-row"><span>${l}</span><b class="number">${v}</b></div>`).join('')}</div>`,`<button class="text-button" data-view="risk" aria-label="Abrir riesgo">${icon('arrow')}</button>`); }
function monitoring() { return state.baseline?reviewPortfolio(data,state.baseline,state.rules):null; }
function overview() {
  const review=monitoring();
  const actions=`<button class="button" data-action="reload">${icon('refresh')}Cargar último corte</button><button class="button" data-action="rules">Criterios</button>`;
  if(!review)return title('SEGUIMIENTO / SIN COMPOSICIÓN REGISTRADA','Seguimiento de cartera','Primero registra una composición con sus precios y fundamentos de referencia.',actions)+panel('ESTADO','01',`<div class="empty-state">No hay una cartera registrada.<br><button class="button primary" data-view="portfolio">Componer cartera</button></div>`);
  const pending=review.alerts.filter(a=>!state.acknowledged.includes(a.id));
  return title('SEGUIMIENTO / CARTERA REGISTRADA','Seguimiento de cartera',`Base ${dateLabel(review.baselineAsOf)} · último corte ${dateLabel(review.currentAsOf)}.`,actions)+
  `${review.missing.length?`<div class="notice">Faltan datos para ${review.missing.map(esc).join(', ')}. No se calcula un rendimiento completo.</div>`:''}`+
  `<div class="metric-grid">${metric('VALOR AJUSTADO TEÓRICO',money(review.currentCapital,0),'Base '+money(state.baseline.capital,0))}${metric('RETORNO DESDE REGISTRO',pct(review.totalReturn,2), 'Precios ajustados del proveedor',color(review.totalReturn))}${metric('REVISIONES PENDIENTES',String(pending.length),'Criterios configurados; no órdenes automáticas',pending.length?'orange':'')}${metric('CARTERA REGISTRADA',String(state.baseline.positions.length)+' activos',dateLabel(state.baseline.as_of))}</div>`+
  panel('REVISIONES POR INFORMACIÓN DISPONIBLE','01',review.alerts.length?`<div class="table-wrap"><table class="alerts-table"><thead><tr><th>PRIORIDAD / ACTIVO</th><th>OBSERVACIÓN</th><th>REVISIÓN SUGERIDA</th><th>ESTADO</th></tr></thead><tbody>${review.alerts.map(a=>`<tr><td><span class="${a.priority==='alta'?'negative':a.priority==='media'?'orange':'muted'}">${a.priority.toUpperCase()}</span><br><button class="text-button" ${asset(a.symbol)?`data-detail="${a.symbol}"`:''}>${esc(a.symbol)}</button></td><td><b>${esc(a.title)}</b><p>${esc(a.reason)}</p>${a.url?`<a href="${url(a.url)}" target="_blank" rel="noopener noreferrer">Presentación SEC ↗</a>`:''}</td><td>${esc(a.review)}</td><td>${state.acknowledged.includes(a.id)?'<span class="muted">REVISADA</span>':`<button class="button small" data-ack="${esc(a.id)}">Marcar revisada</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state" style="padding:24px">No se activó ningún criterio con este corte.</div>',`<button class="text-button" data-action="notifications">Activar avisos</button>`, `<span>Las alertas indican qué revisar. Las de valoración dependen de los supuestos guardados.</span>`)+
  `<div class="section-gap">${panel('COMPOSICIÓN REGISTRADA / EVOLUCIÓN','02',`<div class="table-wrap"><table><thead><tr><th>ACTIVO</th><th>PESO REGISTRADO</th><th>PESO AJUSTADO ACTUAL</th><th>RETORNO AJUSTADO</th><th>PRECIO REFERENCIA</th><th>ÚLTIMO PRECIO</th><th>VALOR MODELO ACTUAL</th></tr></thead><tbody>${review.positions.map(p=>`<tr><td><button class="text-button" data-detail="${p.symbol}">${p.symbol}</button></td><td>${pct(p.weight)}</td><td>${pct(p.currentWeight)}</td><td class="${color(p.return)}">${pct(p.return,2,true)}</td><td>${money(p.price)}</td><td>${money(p.asset.price)}</td><td>${money(p.currentModel?.fairValue)}</td></tr>`).join('')}</tbody></table></div>`,'',`<span>Evolución teórica con Adj Close y unidades iniciales constantes. No sustituye la conciliación con el broker.</span>`)}</div>`+
  `<div class="two-column section-gap">${riskMonitor(review.analysis)}${panel('REGISTRO Y AVISOS','03',`<div class="optimization"><p>Referencia guardada el ${dateLabel(state.baseline.registered_at)}, usando el corte ${dateLabel(state.baseline.as_of)}. Los cambios de pesos del constructor no alteran esta base hasta registrar otra composición.</p><p>La referencia se guarda en este navegador. Exporta la cartera para conservarla o pasarla a otro equipo.</p><p>La evaluación se ejecuta al cargar otro corte. Los avisos del navegador requieren mantener la página abierta y dar permiso.</p><button class="button" data-action="export">Exportar referencia y supuestos</button></div>`)}</div>`;
}

function tableSort(key,label) { return `<button data-sort="${key}">${label}${state.sort.key===key?(state.sort.ascending?' ↑':' ↓'):''}</button>`; }
function renderTable(assets,compactTable=false) {
  if(!assets.length)return '<div class="empty-state">No hay activos con estos filtros.<br><button class="button" data-action="clear-filters">Restablecer filtros</button></div>';
  return `<div class="table-wrap"><table class="${compactTable?'':'full-table'}"><thead><tr><th>${tableSort('symbol','ACTIVO')}</th><th>${tableSort('price','PRECIO')}</th><th>${tableSort('change','1D %')}</th><th>${tableSort('pe','P/E')}</th>${compactTable?'':`<th>${tableSort('fcfYield','FCF YIELD')}</th><th>${tableSort('volatility','VOL. ANUAL')}</th>`}<th>${tableSort('upside','VS MODELO')}</th><th>3 MESES</th><th></th></tr></thead><tbody>${assets.map(a=>{const m=metrics(a),v=model(a),added=state.positions.some(p=>p.symbol===a.symbol);return `<tr><td><button class="security-name" data-detail="${a.symbol}"><span class="ticker-logo">${a.symbol.slice(0,2)}</span><span class="ticker-info"><b>${a.symbol}<span class="dim"> US</span></b><small>${esc(a.name)}</small></span></button></td><td>${money(a.price)}</td><td class="${color(a.change)}">${pct(a.change,2,true)}</td><td>${finite(m.pe)?fmt(m.pe,1)+'x':'—'}</td>${compactTable?'':`<td class="${color(m.fcfYield)}">${pct(m.fcfYield)}</td><td>${pct(assetStats(a)?.volatility)}</td>`}<td class="${color(v?.upside)}" title="Valor presente del modelo / precio − 1; depende de supuestos editables">${pct(v?.upside,1,true)}</td><td>${sparkline(a.history.slice(-63).map(r=>r.adj_close),a.history.at(-1).adj_close>=a.history.at(-63)?.adj_close?'#41b891':'#d16e76')}</td><td><button class="add-button ${added?'added':''}" data-add="${a.symbol}" aria-label="${added?'Quitar':'Agregar'} ${a.symbol} ${added?'del':'al'} portafolio">${added?'✓':'+'}</button></td></tr>`;}).join('')}</tbody></table></div>`;
}
function filteredAssets() {const f=state.filters;return data.assets.filter(a=>(!f.text||`${a.symbol} ${a.name}`.toLowerCase().includes(f.text.toLowerCase()))&&(f.sector==='all'||a.sector===f.sector)&&(f.type==='all'||a.type===f.type)&&(!f.discount||(model(a)?.upside||0)>0)).sort((a,b)=>{const k=state.sort.key;let av=k==='symbol'?a.symbol:['price','change'].includes(k)?a[k]:k==='upside'?model(a)?.upside:k==='volatility'?assetStats(a)?.volatility:metrics(a)[k];let bv=k==='symbol'?b.symbol:['price','change'].includes(k)?b[k]:k==='upside'?model(b)?.upside:k==='volatility'?assetStats(b)?.volatility:metrics(b)[k];if(av==null)return 1;if(bv==null)return -1;return (typeof av==='string'?av.localeCompare(bv):av-bv)*(state.sort.ascending?1:-1);});}
function research() { const sectors=[...new Set(data.assets.map(a=>a.sector))];return title('ACTIVOS / FUNDAMENTOS','Research de activos','Precios, múltiplos, generación de caja y comparación con tu valoración.',`<button class="button" data-action="export-research">${icon('download')}Exportar CSV</button>`)+panel('EQUITY & ETF SCREENER','01',`<div class="filters"><div class="filter-search">${icon('search')}<input id="research-search" placeholder="Buscar ticker o empresa" value="${esc(state.filters.text)}" aria-label="Buscar en el universo"></div><select id="sector-filter" aria-label="Filtrar sector"><option value="all">Todos los sectores</option>${sectors.map(s=>`<option ${state.filters.sector===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="type-filter" aria-label="Filtrar tipo"><option value="all">Acciones + ETFs</option><option value="stock" ${state.filters.type==='stock'?'selected':''}>Acciones</option><option value="etf" ${state.filters.type==='etf'?'selected':''}>ETFs</option></select><label class="filter-toggle"><input id="discount-filter" type="checkbox" ${state.filters.discount?'checked':''}>Descuento modelo</label></div><div id="screener-table">${renderTable(filteredAssets())}</div>`,`<span class="panel-meta">${data.assets.length} ACTIVOS</span>`,`<span>FCF = CFO − capex; excluido para el sector financiero. — indica falta de datos comparables.</span>`); }
function validationPanel() {const v=state.validation;return panel('COMPROBACIÓN FUERA DE MUESTRA','04',`<div class="validation-body"><div class="validation-headline"><div><p class="small muted mono">COBERTURA OBSERVADA · BANDA 90%</p><div class="validation-number ${v&&v.coverage<.8?'negative':'positive'}" style="margin-top:12px">${pct(v?.coverage,0)}</div></div><span class="tag">${v?.count||0} VENTANAS</span></div><div class="validation-bars">${v?.results.map(r=>`<span class="${r.covered?'':'miss'}" title="${r.date} · Realizado ${pct(r.realized)} · Banda ${pct(r.low)} / ${pct(r.high)}"></span>`).join('')||''}</div><p>Entrenamiento de 126 sesiones; evaluación en las 21 siguientes, sin solapamiento. EWMA con centro logarítmico cero.</p><p>Valida bandas de riesgo. El ancla fundamental y los saltos todavía no cuentan con validación histórica.</p></div>`,`<span class="panel-meta">WALK FORWARD</span>`); }
function forecastControls() {const s=state.settings;return panel('PARÁMETROS','02',`<div class="forecast-controls"><div class="field"><label for="model-select">PROCESO ESTOCÁSTICO</label><select id="model-select" data-setting="model"><option value="merton" ${s.model==='merton'?'selected':''}>Merton · difusión + saltos</option><option value="gbm" ${s.model==='gbm'?'selected':''}>GBM · difusión lognormal</option></select></div><div class="field"><label for="horizon-select">HORIZONTE</label><select id="horizon-select" data-setting="horizon" data-numeric><option value="0.25" ${s.horizon===.25?'selected':''}>3 meses</option><option value="0.5" ${s.horizon===.5?'selected':''}>6 meses</option><option value="1" ${s.horizon===1?'selected':''}>1 año</option><option value="3" ${s.horizon===3?'selected':''}>3 años</option></select></div><div class="field"><label for="drift-select">ANCLA DEL RETORNO</label><select id="drift-select" data-setting="driftMode"><option value="fundamental" ${s.driftMode==='fundamental'?'selected':''}>Valoración fundamental propia</option><option value="manual" ${s.driftMode==='manual'?'selected':''}>Retorno manual por activo</option></select></div><div class="field"><label for="manual-return">RETORNO MANUAL / SIN FUNDAMENTOS</label><div class="input-unit"><input id="manual-return" type="number" min="-80" max="100" step="1" value="${fmt(s.manualReturn*100,0)}" data-setting="manualReturn" data-scale="100"><span>%/año</span></div></div><div class="field-row"><div class="field"><label for="path-count">TRAYECTORIAS</label><select id="path-count" data-setting="paths" data-numeric>${[1000,3000,5000].map(n=>`<option value="${n}" ${s.paths===n?'selected':''}>${n.toLocaleString('en-US')}</option>`).join('')}</select></div><div class="field"><label for="lambda">EWMA λ</label><select id="lambda" data-setting="lambda" data-numeric>${[.94,.97,.99].map(n=>`<option ${s.lambda===n?'selected':''}>${n}</option>`).join('')}</select></div></div>${s.model==='merton'?`<div class="field-row"><div class="field"><label for="jump-intensity">SALTOS / AÑO</label><input id="jump-intensity" type="number" min="0" max="5" step="0.05" value="${s.jumpIntensity}" data-setting="jumpIntensity" data-numeric></div><div class="field"><label for="jump-mean">SALTO LOG. MEDIO %</label><input id="jump-mean" type="number" min="-80" max="50" step="1" value="${fmt(s.jumpMean*100,0)}" data-setting="jumpMean" data-scale="100"></div></div><div class="forecast-input-note">Dispersión log. del salto: <b>${pct(s.jumpVol,0)}</b>. Salto común a la cartera; parámetros de estrés propios, no estimados.</div>`:''}<div class="forecast-input-note">Volatilidad/covarianza EWMA con regularización del 5%. Ancla fundamental: <b>${state.forecast?pct(state.forecast.coverage,0):'—'}</b> del peso. El resto utiliza el retorno manual.</div><button class="button primary" data-action="resimulate">${icon('refresh')}${state.busy?'Calculando…':'Recalcular simulación'}</button><div class="forecast-input-note">Semilla ${s.seed}. Probabilidades condicionales al modelo; no son confianza estadística sobre el retorno real.</div></div>`); }
function forecastsView() {const f=state.forecast;return title('PROYECCIONES / MONTE CARLO','Simulación de cartera','GBM y difusión con saltos. Supuestos de retorno y covarianza EWMA.',`<button class="button" data-action="export-forecast">${icon('download')}Resultados</button>`)+simulationMetrics()+`<div class="forecast-layout"><div>${forecastPanel(true)}<div class="two-column section-gap">${panel('RETORNOS TERMINALES','03',histogram(f),`<span class="panel-meta">${state.settings.horizon*12} MESES</span>`,`<span>Colas agrupadas en extremos · retorno acumulado</span>`)}${validationPanel()}</div></div>${forecastControls()}</div><div class="section-gap">${panel('SUPUESTOS DE RETORNO POR ACTIVO','05',`<div class="table-wrap"><table><thead><tr><th>ACTIVO</th><th>ANCLA ANUAL</th><th>FUENTE DEL SUPUESTO</th><th>MODELO</th></tr></thead><tbody>${f?.drifts.map(d=>`<tr><td><button class="text-button" data-detail="${d.symbol}">${d.symbol}</button></td><td class="${color(d.annual)}">${pct(d.annual,1,true)}</td><td>${esc(d.source)}</td><td><button class="text-button" data-value="${d.symbol}">Editar valoración ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="4">Calculando…</td></tr>'}</tbody></table></div>`,'',`<span>El modelo usa la CAGR de valoración como ancla de la media terminal. Los dividendos no se suman de nuevo.</span>`)}</div>`; }
function portfolio() {const a=analyze(),w=normalizeWeights(state.positions),total=sum(state.positions.map(p=>p.weight));return title('CARTERA / POSICIONES','Composición de cartera','Pesos por activo y capital de simulación.',`<button class="button ghost" data-action="equal">Igualar pesos</button><button class="button primary" data-action="register" ${!state.positions.some(p=>p.weight>0)||Math.abs(total-1)>.0001?'disabled':''}>Registrar composición</button>`)+`${state.positions.length&&Math.abs(total-1)>.0001?`<div class="notice">Los pesos suman ${pct(total,2)}. Las métricas utilizan pesos normalizados.<button class="text-button" data-action="normalize">Ajustar a 100%</button></div>`:''}<div class="portfolio-grid">${panel('POSICIONES','01',state.positions.length?`<div class="table-wrap"><table class="weights-table"><thead><tr><th>ACTIVO</th><th>PRECIO</th><th>PESO</th><th>CAPITAL ASIGNADO</th><th>CONTRIB. AL RIESGO</th><th></th></tr></thead><tbody>${state.positions.map(p=>{const x=asset(p.symbol);return `<tr><td><button class="security-name" data-detail="${p.symbol}"><span class="ticker-logo">${p.symbol.slice(0,2)}</span><span class="ticker-info"><b>${p.symbol}</b><small>${esc(x.name)}</small></span></button></td><td>${money(x.price)}</td><td><div class="weight-cell"><input type="number" min="0" max="100" step="0.5" value="${fmt(p.weight*100,2)}" data-weight="${p.symbol}" aria-label="Peso ${p.symbol}"><span>%</span></div></td><td>${money((w.find(v=>v.symbol===p.symbol)?.weight||0)*state.capital,0)}</td><td>${pct(a?.contributions.find(c=>c.symbol===p.symbol)?.fraction)}</td><td><button class="icon-button" style="width:24px;height:24px" data-remove="${p.symbol}" aria-label="Quitar ${p.symbol}">${icon('close')}</button></td></tr>`;}).join('')}</tbody></table></div><div class="total-row"><span>PESO TOTAL</span><b class="${Math.abs(total-1)<.0001?'positive':'orange'}">${pct(total,2)}</b></div>`:`<div class="empty-state" style="padding:18px;text-align:left">Selecciona los activos del corte ${dateLabel(data.price_as_of)}.<div class="asset-picker">${data.assets.map(x=>`<button class="button" data-add="${x.symbol}">+ ${x.symbol}</button>`).join('')}</div><button class="text-button" data-view="research">Abrir research de activos »</button></div>`,`<button class="text-button" data-view="research">+ AGREGAR ACTIVO</button>`)}<div class="research-stack" style="grid-template-columns:1fr">${panel('DISTRIBUCIÓN','02',allocation(a))}${panel('CAPITAL & ARCHIVO','03',`<div class="optimization"><div class="field"><label for="capital-input">CAPITAL DE SIMULACIÓN · USD</label><input id="capital-input" type="number" min="100" max="1000000000" step="1000" value="${state.capital}"></div><p class="mini-note">Corte de composición: ${dateLabel(data.price_as_of)}. Se registra una referencia de pesos y precios; no operaciones de un broker.</p><button class="button" data-action="export">${icon('download')}Exportar cartera</button><button class="button ghost" data-action="import-portfolio">${icon('upload')}Importar cartera</button></div>`)}</div></div><div class="two-column section-gap">${panel('EXPOSICIÓN SECTORIAL','04',bars(Object.entries(a?.sectors||{}).sort((a,b)=>b[1]-a[1])))}${riskMonitor(a)}</div>`; }
function bars(entries, signed=false) {return `<div class="bar-list">${entries.map(([label,value],i)=>`<div class="bar-item"><div class="bar-item-label"><span>${esc(label)}</span><b class="${signed?color(value):''}">${pct(value)}</b></div><div class="bar-item-track"><div class="bar-item-fill" style="width:${Math.min(100,Math.abs(value)*100)}%;background:${signed&&value<0?'#7ebeff':'#ff9f00'}"></div></div></div>`).join('')||'<div class="muted small">Sin posiciones.</div>'}</div>`;}
function riskView() {const a=analyze(),s=a?.stats;const points=a?.selected.map(x=>{const s=assetStats(x);return {symbol:x.symbol,x:s?.volatility,y:s?.annualized};})||[];const biggest=a?.weights.reduce((x,y)=>x.weight>y.weight?x:y,{weight:0});return title('RIESGO / EXPOSICIONES','Riesgo de cartera','Volatilidad, correlaciones, drawdown y pérdidas de cola.',`<div class="panel-controls"><button class="button small ${state.lookback===252?'active':''}" data-lookback="252">1 AÑO</button><button class="button small ${state.lookback===500?'active':''}" data-lookback="500">2 AÑOS</button></div>`)+`<div class="metric-grid">${metric('VOLATILIDAD ANUAL',pct(s?.volatility),'Desv. estándar diaria × √252')}${metric('CVAR 95% · 1 DÍA',pct(s?.expectedShortfall),'Histórico · media del peor 5%','negative')}${metric('MÁXIMO DRAWDOWN',pct(s?.maxDrawdown),'Desde máximos · ventana seleccionada','negative')}${metric('CORRELACIÓN MEDIA',fmt(a?.averageCorrelation,2),`${a?.stats.n||0} retornos comunes · Pearson`)}</div><div class="two-column">${panel('MATRIZ DE CORRELACIÓN','01',`<div class="heatmap-wrap">${heatmap(a)}</div><div class="heatmap-key"><span>−1.00</span><div class="heatmap-gradient"></div><span>+1.00</span><span style="margin-left:auto">RETORNOS DIARIOS</span></div>`)}${panel('RIESGO / RETORNO HISTÓRICO','02',scatter(points,s?{x:s.volatility,y:s.annualized}:null),'<span class="panel-meta">RETORNO ANUALIZADO ↑</span>')}</div><div class="two-column section-gap">${panel('CONTRIBUCIÓN A LA VARIANZA','03',bars((a?.contributions||[]).map(c=>[c.symbol,c.fraction]),true),'',`<span>wᵢ(Σw)ᵢ / (w′Σw). Puede ser negativa si un activo cubre riesgo.</span>`)}${panel('CAÍDAS DESDE MÁXIMOS','04',portfolioChart(a,{height:230,drawdown:true}))}</div><div class="section-gap">${panel('ESCENARIOS DE ESTRÉS','05',`<div class="stress-grid"><div class="stress-card"><label>SPY CAE 20%</label><strong>${pct(finite(s?.beta)?-.2*s.beta:null)}</strong><p>Sensibilidad lineal β × shock, sin residuo.</p></div><div class="stress-card"><label>PRINCIPAL POSICIÓN CAE 30%</label><strong>${pct(biggest?-.3*biggest.weight:null)}</strong><p>${esc(biggest?.symbol||'—')} · resto de activos constante.</p></div><div class="stress-card"><label>DRAWDOWN SUPERA 20%</label><strong>${pct(state.forecast?.drawdownProbability)}</strong><p>Probabilidad simulada · ${state.settings.horizon*12} meses, pasos semanales.</p></div></div>`,'',`<span>Escenarios independientes. Las correlaciones y betas pueden cambiar en episodios de estrés.</span>`)}</div>`; }
function valuationView() {const a=asset(state.selected)||data.assets[0],m=metrics(a),v=model(a,state.method),ass={...a.assumptions,...override(a.symbol)},sc=scenarios(a,override(a.symbol),state.method);return title('VALORACIÓN / SUPUESTOS','Valoración por múltiplos','Valor presente según crecimiento, múltiplo de salida y tasa de descuento.',`<button class="button" data-action="reset-valuation">Restablecer supuestos</button>`)+`<div class="valuation-top"><div class="asset-select"><select id="valuation-asset" aria-label="Activo a valorar">${data.assets.map(x=>`<option value="${x.symbol}" ${a.symbol===x.symbol?'selected':''}>${x.symbol} · ${esc(x.name)}</option>`).join('')}</select><div class="asset-current">${money(a.price)}<small>CIERRE ${dateLabel(a.price_date)}</small></div></div><span class="tag orange">MODELO PROPIO · ${ass.horizon||3} AÑOS</span></div><div class="valuation-grid">${panel('SUPUESTOS','01',`<div class="method-picker"><button class="button ${state.method==='pe'?'active':''}" data-method="pe">BPA × P/E</button><button class="button ${state.method==='fcf'?'active':''}" data-method="fcf">FCF × P/FCF</button></div><div class="assumptions">${[['growth','CRECIMIENTO ANUAL',-30,60,1,100,'%'],['multiple','MÚLTIPLO DE SALIDA',5,60,1,1,'x'],['discount','RENTABILIDAD EXIGIDA',1,30,.5,100,'%'],['horizon','HORIZONTE · AÑOS',1,5,1,1,'a']].map(([key,label,min,max,step,scale,unit])=>`<div class="field"><div class="field-topline"><label for="assumption-${key}">${label}</label><output id="output-${key}">${finite(ass[key])?fmt(ass[key]*scale,key==='multiple'||key==='horizon'?0:1):'—'}${unit}</output></div><input id="assumption-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${(ass[key]??(key==='multiple'?20:key==='growth'?.06:key==='horizon'?3:.10))*scale}" data-assumption="${key}" data-scale="${scale}"></div>`).join('')}<div class="forecast-input-note" style="grid-column:1/-1">Estos supuestos alimentan el ancla de retorno del módulo de proyecciones. P/FCF es un múltiplo simplificado sobre CFO − capex; no es un DCF.</div></div>`)}${panel('VALOR PRESENTE DEL MODELO','02',v?`<div class="fair-value-result"><div><div class="result-label">VALOR POR ACCIÓN · HOY</div><div class="result-number">${money(v.fairValue)}</div><div class="result-sub">Precio de mercado ${money(a.price)}</div></div><div><div class="result-label">VS PRECIO ACTUAL</div><div class="result-discount ${color(v.upside)}">${pct(v.upside,1,true)}</div><div class="result-sub">${v.upside>0?'Descuento bajo estos supuestos':'Prima bajo estos supuestos'}</div></div></div><div class="valuation-ruler"><div class="ruler-track"><i class="ruler-marker" style="left:${Math.max(8,Math.min(92,a.price/Math.max(a.price,v.fairValue)*75))}%"><span>PRECIO</span></i><i class="ruler-marker model" style="left:${Math.max(8,Math.min(92,v.fairValue/Math.max(a.price,v.fairValue)*75))}%"><span>MODELO</span></i></div><div class="ruler-legend"><span>MAYOR MARGEN DE SEGURIDAD</span><span>MENOR</span></div></div><div class="table-wrap"><table class="scenario-table"><thead><tr><th>ESCENARIO</th><th>CRECIMIENTO</th><th>MÚLTIPLO</th><th>PRECIO AL HORIZONTE</th><th>RETORNO ANUAL</th></tr></thead><tbody>${sc.map(s=>`<tr><td>${s.label}</td><td>${pct(s.result?.assumptions.growth,0)}</td><td>${fmt(s.result?.assumptions.multiple,1)}x</td><td>${money(s.result?.exitPrice)}</td><td class="${color(s.result?.annualReturn)}">${pct(s.result?.annualReturn,1,true)}</td></tr>`).join('')}</tbody></table></div><div class="equation"><strong>${state.method==='pe'?'BPA':'FCF/acción'} ${money(v.base)}</strong> × (1 + ${pct(ass.growth,0)})<sup>${ass.horizon}</sup> × ${fmt(ass.multiple,0)}x → <strong>${money(v.exitPrice)}</strong> al horizonte.<br>Descuento al ${pct(ass.discount,0)} + dividendos constantes descontados → ${money(v.fairValue)} hoy.</div>`:'<div class="empty-state">Este activo no tiene una base positiva y comparable para este modelo.<br>Selecciona otra acción o revisa la disponibilidad de fundamentos.<br><span class="small">Los ETFs se proyectan con el supuesto manual del módulo de proyecciones.</span></div>')}</div><div class="section-gap">${panel('BASE FINANCIERA','03',financialTable(a),`<a class="text-button" href="${url(a.financials?.source_url||a.source_url)}" target="_blank" rel="noopener noreferrer">VER FUENTE ↗</a>`,`<span>${m.periodType||'—'} al ${dateLabel(m.period)} · presentación ${dateLabel(m.filed)}. Sin consenso externo.</span>`)}</div>`; }
function financialTable(a) {const m=metrics(a),f=a.financials||{};return `<div class="table-wrap"><table class="financial-table"><tbody>${[['Ingresos',compact(m.revenue),f.revenue],['BPA diluido',money(m.eps),f.eps],['Flujo de operación',compact(m.cfo),f.cfo],['Inversión en activos · capex',compact(m.capex),f.capex],['FCF simple',compact(m.fcf),f.cfo],['Efectivo',compact(m.cash),f.cash],['Patrimonio',compact(m.equity),f.equity],['Acciones en circulación',finite(m.shares)?fmt(m.shares/1e9,3)+' B':'—',f.shares]].map(([label,value,record])=>`<tr><td>${label}</td><td>${value}</td><td>${dateLabel(record?.period_end)} ${record?.method||''}</td></tr>`).join('')}</tbody></table></div>`; }
function macroView() {
  const ten=data.macro.find(s=>s.id==='DGS10'),two=data.macro.find(s=>s.id==='DGS2');
  return title('MACRO / ESTADOS UNIDOS','Tasas y datos macro','Curva nominal del Treasury, IPC y desempleo. Fechas por serie.')+`${ten&&two?`<div class="notice neutral">10Y − 2Y: <b class="mono">${fmt((ten.value-two.value)*100,0)} pb</b><span class="muted">· ${dateLabel(ten.date)}</span></div>`:''}`+panel('SERIES DISPONIBLES','01',`<div class="table-wrap"><table class="full-table macro-table"><thead><tr><th>SERIE</th><th>ÚLTIMO</th><th>ANTERIOR</th><th>FECHA / PERÍODO</th><th>HISTORIA</th><th>FUENTE</th></tr></thead><tbody>${data.macro.map(s=>`<tr><td>${esc(s.label)}${s.id==='CPI'?' · interanual':''}</td><td>${s.id==='CPI'&&finite(s.yoy)?pct(s.yoy):fmt(s.value,2)+(s.unit==='%'?'%':'')}</td><td>${s.id==='CPI'?fmt(s.previous,2)+' índice':fmt(s.previous,2)+(s.unit==='%'?'%':'')}</td><td>${dateLabel(s.date)}</td><td>${sparkline(s.history.map(r=>r.value),'#ff9f00',140,30)}</td><td><a href="${url(s.source_url)}" target="_blank" rel="noopener noreferrer">${s.id==='CPI'||s.id==='UNRATE'?'BLS':'Treasury'} ↗</a></td></tr>`).join('')}</tbody></table></div>`,'',`<span>Macro como contexto. Estas series todavía no se usan como predictores del retorno.</span>`);
}

function sourcesView() {const errors=data.errors||[];return `<div class="data-health"><div><label>PRECIOS AL CIERRE</label><b>${dateLabel(data.price_as_of)}</b></div><div><label>UNIVERSO / COBERTURA</label><b>${data.assets.length} activos</b></div><div><label>FUNDAMENTOS CON BPA</label><b>${data.assets.filter(a=>metrics(a).eps>0).length} acciones</b></div></div><div class="sources-grid">${(data.sources||[]).map(s=>`<div class="source-card"><h3>${esc(s.name)}</h3><span class="tag" style="display:inline-block;margin-top:10px">${esc(s.kind)}</span><p>${esc(s.data)}</p><a href="${url(s.url)}" target="_blank" rel="noopener noreferrer">Documentación / fuente ↗</a></div>`).join('')}</div><p class="mini-note">Corte generado ${dateLabel(data.generated_at)}. La página utiliza un archivo de datos descargados; no representa un feed en tiempo real. La actualización de proveedores se ejecuta con scripts/refresh_data.py o el workflow manual del repositorio.</p>${errors.length?`<div class="notice section-gap">${errors.map(esc).join('<br>')}</div>`:''}<div class="inline-actions section-gap"><button class="button" data-action="reload">${icon('refresh')}Cargar último corte publicado</button><button class="button" data-action="import-snapshot">${icon('upload')}Importar corte JSON</button><a class="button" href="https://github.com/Hardnyx/Trading" target="_blank" rel="noopener noreferrer">Repositorio ↗</a></div><div class="section-gap">${panel('COBERTURA Y FECHAS','',`<div class="table-wrap"><table class="coverage-table"><thead><tr><th>ACTIVO</th><th>PRECIO</th><th>FUNDAMENTOS</th><th>PRESENTACIÓN</th><th>P/E</th><th>FCF YIELD</th></tr></thead><tbody>${data.assets.map(a=>{const m=metrics(a);return `<tr><td>${a.symbol}</td><td>${dateLabel(a.price_date)}</td><td>${dateLabel(m.period)}</td><td>${dateLabel(m.filed)}</td><td>${m.pe?'DISPONIBLE':'—'}</td><td>${finite(m.fcfYield)?'DISPONIBLE':'—'}</td></tr>`;}).join('')}</tbody></table></div>`)}</div>`; }
function methodologyView() {return `<ol class="methodology-list"><li><b>Datos observados.</b> Precios diarios y Adj Close de Yahoo Finance (endpoint público no oficial). SEC Company Facts para conceptos estándar de la entidad. Los valores ausentes permanecen ausentes. Múltiples clases de acciones y conceptos personalizados limitan la cobertura.</li><li><b>Ratios.</b> P/E = precio / BPA diluido TTM. TTM usa anual + acumulado actual − acumulado anterior, o anual cuando no puede reconstruirse. FCF = CFO − capex con períodos compatibles; FCF yield usa acciones en circulación recientes y no se aplica a bancos/servicios financieros. Las fechas están en cada activo.</li><li><b>Valoración.</b> BPA o FCF/acción proyectado × múltiplo de salida, descontado a la tasa exigida; dividendos por acción constantes. El retorno anual equivalente aproxima todos los dividendos como efectivo al final del horizonte. Crecimiento y múltiplos son supuestos ilustrativos editables.</li><li><b>Difusión correlacionada.</b> dSᵢ/Sᵢ = (μᵢ − λκ)dt + (L dW)ᵢ + (eᴶ−1)dN. L factoriza la covarianza EWMA de retornos logarítmicos (252 sesiones/año), con regularización diagonal del 5%. Volatilidad y correlaciones se mantienen constantes en la proyección. μᵢ = ln(1 + retorno anual del ancla).</li><li><b>Saltos.</b> En Merton, N es Poisson y J es normal con media y dispersión configuradas. Un mismo salto afecta a todos los activos: es una extensión de estrés sistémico. κ = exp(media + dispersión²/2) − 1 compensa la media. Los saltos se añaden a la volatilidad observada; no se calibran separadamente y pueden aumentar el riesgo total.</li><li><b>Simulación.</b> Trayectorias semanales buy & hold, sin costos ni impuestos; el ancla incorpora dividendos para evitar doble conteo. P05–P95 es una banda entre cuantiles del modelo, no un intervalo de confianza sobre el futuro real. La probabilidad de drawdown usa pasos semanales y puede omitir mínimos intradiarios. Semilla reproducible.</li><li><b>Riesgo histórico.</b> Retornos simples ajustados, fechas comunes, covarianza muestral, volatilidad anualizada √252. Cartera de pesos constantes (rebalanceo diario teórico). VaR histórico al 95% y CVaR a 1 día; Monte Carlo al horizonte configurado. La tasa de 3 meses del Treasury sirve de aproximación para Sharpe; si falta, se usa 4% explícito.</li><li><b>Comprobación.</b> Walk forward con 126 sesiones pasadas y 21 futuras no solapadas. Evalúa cobertura de bandas EWMA al 90% centradas en retorno logarítmico cero. No evalúa el ancla fundamental, selección del universo ni parámetros de saltos. La muestra disponible es pequeña.</li><li><b>Capacidad predictiva.</b> Universo actual seleccionado y últimos estados rectificados. No es un backtest point-in-time. Las fuentes macro se muestran como contexto y todavía no alimentan una estimación causal del retorno. La simulación cuantifica supuestos; no demuestra capacidad de generar alpha.</li></ol><div class="source-card"><h3>Referencias del modelo</h3><a href="https://dspace.mit.edu/entities/publication/e63635d9-d2bf-40ce-a79b-67786dd9f105" target="_blank" rel="noopener noreferrer">Merton · Option pricing when underlying stock returns are discontinuous ↗</a><br><a href="https://www.msci.com/research-and-insights/paper/1996-riskmetrics-technical-document" target="_blank" rel="noopener noreferrer">RiskMetrics · Technical Document ↗</a></div>`; }
function render() {
  if(!data)return;
  const editing=document.activeElement;
  const preserve=editing?.tagName==='INPUT'&&editing.closest('#app')?{id:editing.id,weight:editing.dataset.weight,value:editing.value,start:editing.selectionStart,end:editing.selectionEnd}:null;
  const nav= NAV.find(n=>n[0]===state.view)||NAV[0];
  const page=({overview,forecasts:forecastsView,research,valuation:valuationView,risk:riskView,portfolio,macro:macroView}[state.view]||overview)();
  $('#app').innerHTML=`<a class="skip-link" href="#workspace-main">Ir al contenido</a><header class="topbar"><a class="brand-lockup" href="#portfolio" aria-label="Trading inicio"><span class="brand">TRADING</span><span class="brand-sub">PORTAFOLIO / ESTADOS UNIDOS</span></a><span class="top-divider"></span><div class="command-wrap"><div class="command-bar"><span>›</span><input id="command-input" placeholder="Ticker, empresa o función…" autocomplete="off" aria-label="Buscar ticker o función"><kbd>/</kbd></div><div id="command-results" class="command-results" hidden></div></div><div class="top-right"><div class="market-status"><div><span class="dot"></span>EE.UU. / CIERRE</div><span>${dateLabel(data.price_as_of)} · USD</span></div><button class="icon-button" data-action="sources" aria-label="Fuentes y estado de datos" title="Fuentes y estado de datos">${icon('data')}</button><button class="icon-button" data-action="help" aria-label="Atajos de teclado" title="Atajos de teclado">${icon('help')}</button></div></header><div class="ticker-strip">${['SPY','QQQ','IWM','TLT','GLD','SHY'].map(s=>{const a=asset(s);return a?`<button class="ticker-item" data-detail="${s}"><span class="ticker-symbol">${s}</span><span class="ticker-price">${fmt(a.price)}</span><span class="change ${color(a.change)}">${a.change>=0?'▴':'▾'} ${pct(Math.abs(a.change),2)}</span></button>`:'';}).join('')}</div><div class="workspace"><main id="workspace-main" class="main-area" tabindex="-1"><div class="function-bar"><div class="path"><span>TRADING</span><span>/</span><b>${esc(nav[1].toUpperCase())}</b></div><div class="right"><span>${state.busy?'CALCULANDO…':'CORTE '+dateLabel(data.price_as_of)}</span><span class="orange">${nav[2]}</span></div></div><nav class="terminal-nav" aria-label="Funciones">${NAV.map(([id,label,key])=>`<button class="terminal-tab ${state.view===id?'active':''}" data-view="${id}" ${state.view===id?'aria-current="page"':''}><b>${key}</b> ${label}</button>`).join('')}</nav><div class="content">${state.forecastError?`<div class="notice">${esc(state.forecastError)}<button class="text-button" data-action="resimulate">REINTENTAR</button></div>`:''}${page}<footer class="footer"><div><span class="footer-brand">TRADING</span> &nbsp; RESEARCH + RISK<br>Datos al cierre · escenarios sujetos a tus supuestos.</div><div class="footer-right"><button data-action="methodology">METODOLOGÍA & LIMITACIONES</button><span>v0.1 &nbsp; / &nbsp; US EQUITIES &nbsp; / &nbsp; USD</span></div></footer></div></main></div>`;
  if(preserve){const input=preserve.id?document.getElementById(preserve.id):preserve.weight?document.querySelector(`[data-weight="${preserve.weight}"]`):null;if(input){input.value=preserve.value;input.focus({preventScroll:true});if(input.type==='text'&&preserve.start!=null)input.setSelectionRange(preserve.start,preserve.end);if(input.id==='command-input'&&input.value)input.dispatchEvent(new Event('input',{bubbles:true}));}}
  persist();
}
function navigate(view) {if(!NAV.some(n=>n[0]===view))return;state.view=view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function runForecast() {
  if(!data)return;
  const current=++job;state.busy=true;state.forecastError=null;
  if(!state.positions.some(p=>p.weight>0)){state.busy=false;state.forecast=null;state.validation=null;render();return;}
  try {
    worker ||= new Worker(new URL('./forecast-worker.mjs',import.meta.url),{type:'module'});
    worker.onmessage=event=>{const r=event.data;if(r.id!==job)return;state.busy=false;if(r.error){state.forecast=null;state.validation=null;state.forecastError=r.error;}else{state.forecast=r.forecast;state.validation=r.validation;}render();};
    worker.onerror=()=>{state.busy=false;state.forecastError='No se pudo ejecutar el motor de simulación. Recarga la página para reintentar.';render();};
    worker.postMessage({id:current,assets:data.assets,positions:state.positions,options:state.settings,overrides:state.overrides});
  }catch(error){state.busy=false;state.forecastError=error.message;}
  render();
}
function changePositions() {state.forecast=null;state.validation=null;persist();runForecast();}
function toggleAsset(symbol) {if(state.positions.some(p=>p.symbol===symbol)){state.positions=state.positions.filter(p=>p.symbol!==symbol);toast(`${symbol} retirado de la cartera.`);}else{state.positions=normalizeWeights([...state.positions,{symbol,weight:state.positions.length?.05:1}]);toast(`${symbol} agregado. Pesos ajustados a 100%.`);}changePositions();}
function showModal(heading,content,wide=false) {lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><header class="modal-header"><h2><span>TRADING /</span>${esc(heading)}</h2><button class="icon-button" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></header><div class="modal-content">${content}</div></section></div>`;document.body.style.overflow='hidden';$('.modal [data-action="close-modal"]').focus();}
function closeModal() {$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function showDetail(symbol) {const a=asset(symbol);if(!a)return;const m=metrics(a),s=assetStats(a),v=model(a);showModal(`${symbol} US EQUITY`,`<div class="modal-title"><div><h3>${esc(a.name)}</h3><small>${esc(a.sector)} · ${a.type==='stock'?'ACCIÓN':'ETF'} · USD</small></div><div class="modal-price">${money(a.price)}<div class="small mono ${color(a.change)}" style="margin-top:8px">${pct(a.change,2,true)} / 1D</div></div></div><div class="detail-metrics">${[['P/E '+(m.periodType||''),m.pe?fmt(m.pe,1)+'x':'—'],['FCF YIELD',pct(m.fcfYield)],['VOLATILIDAD ANUAL',pct(s?.volatility)],['VS MODELO',pct(v?.upside,1,true)]].map(([l,v])=>`<div class="detail-metric"><label>${l}</label><b>${v}</b></div>`).join('')}</div><div class="panel">${lineChart([{name:symbol,color:'#ff982b',values:a.history.slice(-252).map(r=>r.close)}],a.history.slice(-252).map(r=>r.date),{height:220,label:'Precio de '+symbol})}</div><p class="mini-note">Precio al ${dateLabel(a.price_date)}. Fundamentos ${m.periodType||'—'} al ${dateLabel(m.period)}; presentados ${dateLabel(m.filed)}. Las métricas ausentes no se estiman.</p><div class="modal-actions"><a class="text-button" href="${url(a.financials?.source_url||a.source_url)}" target="_blank" rel="noopener noreferrer">Documento / fuente ↗</a><div><button class="button" data-add="${symbol}">${state.positions.some(p=>p.symbol===symbol)?'Quitar de cartera':'+ Agregar a cartera'}</button><button class="button primary" data-value="${symbol}">Valorar ${icon('arrow')}</button></div></div>`);}
function download(name,body,type='application/json') {const blob=new Blob([body],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function portfolioExport() {download('trading-cartera.json',JSON.stringify({version:1,price_as_of:data.price_as_of,positions:state.positions,capital:state.capital,settings:state.settings,overrides:state.overrides,baseline:state.baseline,rules:state.rules,acknowledged:state.acknowledged},null,2));toast('Cartera y supuestos exportados.');}
function rulesView() {return `<div class="forecast-controls">${[['weightDrift','DESVÍO DE PESO · PUNTOS PORCENTUALES'],['valuationPremium','PRIMA DEL PRECIO SOBRE VALOR MODELO · %'],['earningsDrop','CAÍDA DEL BPA VS REFERENCIA · %'],['volatilityIncrease','AUMENTO RELATIVO DE VOLATILIDAD · %'],['drawdown','PÉRDIDA DESDE REGISTRO · %']].map(([key,label])=>`<div class="field"><label for="rule-${key}">${label}</label><input id="rule-${key}" data-rule="${key}" type="number" min="1" max="100" step="1" value="${fmt(state.rules[key]*100,0)}"></div>`).join('')}<p class="mini-note">Umbrales iniciales de trabajo, no calibrados para maximizar rendimientos. Los avisos de nuevos documentos SEC son informativos.</p></div>`;}
function notifyReview(previousIds=[]) {if(!state.baseline)return;const r=monitoring();const fresh=r.alerts.filter(a=>!previousIds.includes(a.id)&&!state.acknowledged.includes(a.id));if(fresh.length&&typeof Notification!=='undefined'&&Notification.permission==='granted')new Notification(`Trading: ${fresh.length} revisiones de cartera`,{body:fresh.slice(0,3).map(a=>`${a.symbol}: ${a.title}`).join('\n'),tag:'trading-review'});}
function exportResearch() {const rows=[['Ticker','Empresa','Fecha precio','Precio USD','Variacion 1D','PE','FCF yield','Volatilidad anual','Valor modelo','Descuento modelo']];for(const a of filteredAssets()){const m=metrics(a),v=model(a);rows.push([a.symbol,a.name,a.price_date,a.price,a.change,m.pe,m.fcfYield,assetStats(a)?.volatility,v?.fairValue,v?.upside]);}download('trading-research.csv','\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
let importKind='portfolio';
function importFile(kind) {importKind=kind;$('#import-file').value='';$('#import-file').click();}
async function loadData() {const response=await fetch(new URL('../data/market.json',import.meta.url),{cache:'no-cache'});if(!response.ok)throw new Error('No se pudo cargar el corte de mercado.');data=validateSnapshot(await response.json());statsCache.clear();state.positions=Array.isArray(state.positions)?state.positions.filter(p=>asset(p.symbol)&&finite(p.weight)&&p.weight>=0&&p.weight<=1):[];state.capital=finite(state.capital)&&state.capital>0?state.capital:100000;state.overrides=state.overrides&&typeof state.overrides==='object'?state.overrides:{};state.settings={model:'merton',horizon:1,paths:3000,seed:20261024,driftMode:'fundamental',manualReturn:.06,lambda:.94,jumpIntensity:.35,jumpMean:-.12,jumpVol:.08,...state.settings};if(!asset(state.selected))state.selected=data.assets[0].symbol;}

// Only checks the published snapshot while the application is open.
setInterval(async()=>{
  if(!data||!state.baseline||document.visibilityState!=='visible')return;
  try{
    const response=await fetch(new URL('../data/market.json',import.meta.url),{cache:'no-cache'});
    if(!response.ok)return;
    const next=validateSnapshot(await response.json());
    if(next.generated_at===data.generated_at)return;
    const previous=monitoring()?.alerts.map(a=>a.id)||[];
    data=next;statsCache.clear();notifyReview(previous);state.forecast=null;runForecast();
  }catch{/* Keep the last valid cut; a failed poll never changes reference data. */}
},300000);

document.addEventListener('click',async event=>{
  const element=event.target.closest('button,[data-view]');
  if(event.target.classList.contains('modal-backdrop')){closeModal();return;}
  if(!element){if(!event.target.closest('.command-wrap'))$('#command-results')?.setAttribute('hidden','');return;}
  if(element.dataset.view){navigate(element.dataset.view);return;}
  if(element.dataset.detail){showDetail(element.dataset.detail);return;}
  if(element.dataset.add){const inModal=!!element.closest('.modal');toggleAsset(element.dataset.add);if(inModal)showDetail(element.dataset.add);return;}
  if(element.dataset.remove){state.positions=state.positions.filter(p=>p.symbol!==element.dataset.remove);changePositions();return;}
  if(element.dataset.ack){state.acknowledged.push(element.dataset.ack);render();return;}
  if(element.dataset.value){state.selected=element.dataset.value;state.method='pe';closeModal();navigate('valuation');return;}
  if(element.dataset.chart){state.chartMode=element.dataset.chart;render();return;}
  if(element.dataset.lookback){state.lookback=Number(element.dataset.lookback);statsCache.clear();render();return;}
  if(element.dataset.method){state.method=element.dataset.method;render();return;}
  if(element.dataset.sort){const key=element.dataset.sort;state.sort={key,ascending:state.sort.key===key?!state.sort.ascending:true};if(state.view==='research')$('#screener-table').innerHTML=renderTable(filteredAssets());else navigate('research');return;}
  const action=element.dataset.action;
  if(action==='close-modal')closeModal();
  if(action==='sources')showModal('DATOS & FUENTES',sourcesView(),true);
  if(action==='rules')showModal('CRITERIOS DE SEGUIMIENTO',rulesView());
  if(action==='register'){
    const total=sum(state.positions.map(p=>p.weight));
    if(!state.positions.some(p=>p.weight>0)){toast('Agrega al menos un activo.');return;}
    if(Math.abs(total-1)>.0001){toast('Ajusta los pesos a 100% antes de registrar.');return;}
    state.baseline=registerPortfolio(data,state.positions,state.capital,state.overrides);state.acknowledged=[];persist();navigate('overview');toast('Composición registrada con precios y fundamentos de referencia.');
  }
  if(action==='notifications'){
    if(typeof Notification==='undefined'||!isSecureContext){toast('Este navegador no permite avisos en esta página.');return;}
    const permission=await Notification.requestPermission();toast(permission==='granted'?'Avisos activados mientras esta página permanezca abierta.':'Los avisos no se activaron. Las revisiones siguen visibles en Seguimiento.');
  }
  if(action==='methodology')showModal('METODOLOGÍA',methodologyView());
  if(action==='help')showModal('ATAJOS DE TECLADO',`<div class="shortcuts">${NAV.map(n=>`<div class="shortcut"><kbd>${n[2]}</kbd>${n[1]}</div>`).join('')}<div class="shortcut"><kbd>/</kbd>Buscar ticker o función</div><div class="shortcut"><kbd>Esc</kbd>Cerrar ventana</div></div>`);
  if(action==='export')portfolioExport();
  if(action==='export-research')exportResearch();
  if(action==='export-forecast'){if(!state.forecast){toast('Espera a que termine la simulación.');return;}download('trading-proyeccion.json',JSON.stringify({price_as_of:data.price_as_of,capital:state.capital,positions:state.positions,forecast:state.forecast,validation:state.validation},null,2));}
  if(action==='resimulate'){runForecast();toast('Simulación recalculada con semilla reproducible.');}
  if(action==='equal'){state.positions=state.positions.map(p=>({...p,weight:1/state.positions.length}));changePositions();}
  if(action==='normalize'){state.positions=normalizeWeights(state.positions);changePositions();}
  if(action==='import-portfolio')importFile('portfolio');
  if(action==='import-snapshot')importFile('snapshot');
  if(action==='reset-valuation'){delete state.overrides[state.selected];state.method='pe';runForecast();}
  if(action==='clear-filters'){state.filters={text:'',sector:'all',discount:false,type:'all'};render();}
  if(action==='reload'){try{const previous=monitoring()?.alerts.map(a=>a.id)||[];await loadData();notifyReview(previous);state.forecast=null;closeModal();runForecast();toast('Corte publicado cargado: '+dateLabel(data.price_as_of));}catch(e){toast(e.message);}}
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.dataset.weight){const value=Number(el.value);if(el.value!==''&&finite(value)&&value>=0&&value<=100){state.positions=state.positions.map(p=>p.symbol===el.dataset.weight?{...p,weight:value/100}:p);job++;state.busy=false;state.forecast=null;state.validation=null;clearTimeout(weightTimer);weightTimer=setTimeout(()=>{persist();runForecast();},350);}}
  if(el.id==='research-search'){state.filters.text=el.value;$('#screener-table').innerHTML=renderTable(filteredAssets());}
  if(el.dataset.assumption){const key=el.dataset.assumption;$('#output-'+key).textContent=fmt(Number(el.value),key==='multiple'||key==='horizon'?0:1)+(key==='multiple'?'x':key==='horizon'?'a':'%');}
  if(el.id==='command-input'){
    const query=el.value.trim().toLowerCase(),r=$('#command-results');
    if(!query){r.hidden=true;return;}
    const matches=data.assets.filter(a=>`${a.symbol} ${a.name}`.toLowerCase().includes(query)).slice(0,5);
    const sections=NAV.filter(n=>n[1].toLowerCase().includes(query));
    r.innerHTML=matches.map(a=>`<button class="command-result" data-detail="${a.symbol}"><span><b class="mono orange">${a.symbol}</b> &nbsp; ${esc(a.name)}</span><span class="muted mono small">${money(a.price)}</span></button>`).join('')+sections.map(n=>`<button class="command-result" data-view="${n[0]}"><span>${n[1]}</span><span class="muted mono small">${n[2]}</span></button>`).join('')||'<div class="empty-state" style="padding:18px">Sin resultados en el universo descargado.</div>';r.hidden=false;
  }
});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.dataset.rule){const value=Number(el.value);if(value>=1&&value<=100){state.rules[el.dataset.rule]=value/100;persist();render();}else toast('El umbral debe estar entre 1 y 100.');}
  if(el.dataset.weight){clearTimeout(weightTimer);const value=Number(el.value);if(!finite(value)||value<0||value>100){toast('El peso debe estar entre 0% y 100%.');render();return;}state.positions=state.positions.map(p=>p.symbol===el.dataset.weight?{...p,weight:value/100}:p);changePositions();}
  if(el.id==='capital-input'){const value=Number(el.value);if(value>0&&value<=1e9){state.capital=value;render();}else{toast('Ingresa un capital positivo, hasta USD 1,000 millones.');render();}}
  if(el.id==='sector-filter'){state.filters.sector=el.value;$('#screener-table').innerHTML=renderTable(filteredAssets());}
  if(el.id==='type-filter'){state.filters.type=el.value;$('#screener-table').innerHTML=renderTable(filteredAssets());}
  if(el.id==='discount-filter'){state.filters.discount=el.checked;$('#screener-table').innerHTML=renderTable(filteredAssets());}
  if(el.id==='valuation-asset'){state.selected=el.value;state.method='pe';render();}
  if(el.dataset.assumption){const key=el.dataset.assumption;state.overrides[state.selected]={...override(state.selected),[key]:Number(el.value)/Number(el.dataset.scale)};state.forecast=null;runForecast();}
  if(el.dataset.setting){const key=el.dataset.setting;const value=el.dataset.scale?Number(el.value)/Number(el.dataset.scale):el.hasAttribute('data-numeric')?Number(el.value):el.value;if(el.type==='number'&&!el.checkValidity()){toast('Revisa el rango permitido del parámetro.');render();return;}state.settings[key]=value;state.forecast=null;runForecast();}
  if(el.id==='import-file'&&el.files[0]){
    try{if(el.files[0].size>15e6)throw new Error('El archivo supera 15 MB.');const input=JSON.parse(await el.files[0].text());
      if(importKind==='snapshot'){data=validateSnapshot(input);statsCache.clear();state.positions=state.positions.filter(p=>asset(p.symbol));toast('Corte importado para esta sesión.');}
      else{if(input.version!==1||!Array.isArray(input.positions)||input.positions.length>100||input.positions.some(p=>!asset(p.symbol)||!finite(p.weight)||p.weight<0||p.weight>1)||new Set(input.positions.map(p=>p.symbol)).size!==input.positions.length)throw new Error('La cartera contiene posiciones inválidas o fuera del universo.');state.positions=input.positions.map(({symbol,weight})=>({symbol,weight}));if(input.capital>0&&input.capital<=1e9)state.capital=input.capital;if(input.overrides&&typeof input.overrides==='object'){for(const [symbol,assumptions] of Object.entries(input.overrides)){if(asset(symbol)&&assumptions&&finite(assumptions.growth)&&assumptions.growth>-.9&&assumptions.growth<=2&&assumptions.multiple>0&&assumptions.multiple<=100&&assumptions.discount>0&&assumptions.discount<1&&assumptions.horizon>=1&&assumptions.horizon<=5)state.overrides[symbol]={growth:assumptions.growth,multiple:assumptions.multiple,discount:assumptions.discount,horizon:assumptions.horizon};}}if(input.settings){const allowed=['gbm','merton'];if(allowed.includes(input.settings.model))state.settings.model=input.settings.model;if([.25,.5,1,3].includes(input.settings.horizon))state.settings.horizon=input.settings.horizon;if(['fundamental','manual'].includes(input.settings.driftMode))state.settings.driftMode=input.settings.driftMode;if(finite(input.settings.manualReturn)&&input.settings.manualReturn>-.8&&input.settings.manualReturn<=1)state.settings.manualReturn=input.settings.manualReturn;}toast('Cartera importada.');}
      if(importKind==='portfolio'&&input.baseline){const b=input.baseline;if(b.version!==1||!Array.isArray(b.positions)||!b.positions.length||b.positions.length>200||!(b.capital>0)||!/^\d{4}-\d{2}-\d{2}$/.test(b.as_of)||!Number.isFinite(Date.parse(b.registered_at))||b.positions.some(p=>!/^[A-Z0-9.^-]{1,12}$/.test(p.symbol)||!finite(p.weight)||p.weight<=0||p.weight>1||!(p.adj_close>0)||!(p.price>0)))throw new Error('La referencia registrada no es válida.');state.baseline=b;state.acknowledged=Array.isArray(input.acknowledged)?input.acknowledged.filter(x=>typeof x==='string').slice(0,1000):[];if(input.rules)for(const key of Object.keys(DEFAULT_RULES))if(finite(input.rules[key])&&input.rules[key]>=.01&&input.rules[key]<=1)state.rules[key]=input.rules[key];}
      closeModal();changePositions();
    }catch(error){toast(error.message||'No se pudo importar el archivo.');}
  }
});
document.addEventListener('keydown',event=>{
  const modal=$('.modal');
  if(event.key==='Escape'){closeModal();$('#command-results')?.setAttribute('hidden','');return;}
  if(modal&&event.key==='Tab'){const f=[...modal.querySelectorAll('button,a[href],input,select')].filter(el=>!el.disabled);if(event.shiftKey&&document.activeElement===f[0]){event.preventDefault();f.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===f.at(-1)){event.preventDefault();f[0].focus();}return;}
  if(event.key==='Enter'&&event.target.id==='command-input'){const button=$('#command-results button');if(button){event.preventDefault();button.click();}return;}
  if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;
  if(event.key==='/'){event.preventDefault();$('#command-input')?.focus();}
  const match=NAV.find(n=>n[2]===event.key);if(match){event.preventDefault();closeModal();navigate(match[0]);}
});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(NAV.some(n=>n[0]===view)){state.view=view;render();}});
try{await loadData();const view=location.hash.slice(1);if(NAV.some(n=>n[0]===view))state.view=view;render();runForecast();}catch(error){$('#app').innerHTML=`<div class="boot"><span class="brand">TRADING</span><p>${esc(error.message)}</p><button class="button" onclick="location.reload()">Volver a cargar</button></div>`;}
